import React, { useState } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import ReportIssue from './components/ReportIssue';
import IssuesTracking from './components/IssuesTracking';
import ApiInspector from './components/ApiInspector';
import Profile from './components/Profile';
import './App.css';

function App() {
  const [showApiModal, setShowApiModal] = useState(false);

  return (
    <Router>
      <div className="app-layout">
        <Sidebar onOpenApiModal={() => setShowApiModal(true)} />
        
        <main className="main-content">
          <header className="top-banner">
            <span>CAMPUS SYSTEM • ONLINE</span>
            <span className="semester-tag">Semester Fall 2026</span>
            <button className="btn-api-preview" onClick={() => setShowApiModal(true)}>
              ⚙ API Output Preview
            </button>
          </header>

          <Routes>
            <Route path="/" element={<Navigate to="/dashboard" replace />} />
            <Route path="/dashboard" element={<Dashboard />} />
            <Route path="/report" element={<ReportIssue />} />
            <Route path="/tracking" element={<IssuesTracking />} />
            <Route path="/api-inspector" element={<ApiInspector />} />
            <Route path="/profile" element={<Profile />} />
          </Routes>
        </main>

        {showApiModal && (
          <div className="modal-overlay">
            <div className="modal-content">
              <div className="modal-header">
                <span>http://localhost:5000/api/issues</span>
                <button onClick={() => setShowApiModal(false)}>Close X</button>
              </div>
              <pre className="json-box">
{`{
  "success": true,
  "count": 5,
  "data": [
    {
      "_id": "64ddbc061aacce17fbb8dae1",
      "title": "Poor sanitation in washrooms",
      "category": "Sanitation",
      "description": "The girl's waiting hall in 2nd floor in terms of sanitation is very poor.",
      "status": "pending",
      "priority": "High"
    }
  ]
}`}
              </pre>
            </div>
          </div>
        )}
      </div>
    </Router>
  );
}

export default App;
